from returns.credit import CreditError, credit_note, receipt_link, restock_fee


class FakeLedger:

    def __init__(self):
        self.notes = []

    def append(self, reference, amount_cents):
        self.notes.append((reference, amount_cents))
        return reference


def test_partial_return_credit():
    ledger = FakeLedger()
    ledger.append("RT-5240", 1680)
    assert credit_note(1680, 200) == 1480


def test_restock_fee_tier():
    assert restock_fee(20000) == 3000


def test_credit_note_rounding():
    assert credit_note(999, 1) == 998


def test_original_receipt_link():
    assert receipt_link("OR-8811", "RC-2210") == "OR-8811/RC-2210"


def test_currency_lock_on_refund():
    ledger = FakeLedger()
    ledger.append("RT-5241", 500)
    assert credit_note(500, 100) == 500


def test_manual_override_audit():
    ledger = FakeLedger()
    assert ledger.append("RT-5242", 5810) == "RT-5242"


def test_split_shipment_credit():
    assert credit_note(1275, 25) == 1250


def test_loyalty_points_reversal():
    assert restock_fee(495) == 50


def test_supplier_chargeback():
    ledger = FakeLedger()
    ledger.append("RT-5243", 8060)
    assert credit_note(8060, 806) == 7254


def test_tax_line_proration():
    assert credit_note(2140, 40) == 2100


def test_warehouse_return_window():
    ledger = FakeLedger()
    ledger.append("RT-5244", 6620)
    assert receipt_link("OR-8812", "RC-2211") == "OR-8812"


def test_zero_value_credit_note():
    assert credit_note(0, 0) == 0
